1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    html, body {
14	      width: 100%;
15	      height: 100%;
16	      overflow: hidden;
17	    }
18	    body {
19	      display: flex;
20	      justify-content: center;
21	      align-items: center;
22	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
23	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
24	    }
25	    .circle-container {
26	      cursor: pointer;
27	      transition: transform 0.3s ease;
28	    }
29	    .circle-container:hover,
30	    .circle-container:focus {
31	      transform: scale(1.05);
32	      outline: none;
33	    }
34	    .circle-container:focus-visible {
35	      outline: 3px solid rgba(255, 255, 255, 0.5);
36	      outline-offset: 8px;
37	      border-radius: 50%;
38	    }
39	    svg {
40	      width: 400px;
41	      height: 400px;
42	      filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
43	      display: block;
44	    }
45	    circle {
46	      fill: #ffffff;
47	      stroke: rgba(255, 255, 255, 0.2);
48	      stroke-width: 2;
49	      transition: fill 0.3s ease, r 0.3s ease;
50	      animation: pulse 3s ease-in-out infinite;
51	    }
52	    .circle-container:hover circle,
53	    .circle-container:focus circle {
54	      fill: #e8f4f8;
55	      r: 205;
56	    }
57	    @keyframes pulse {
58	      0%, 100% { r: 200; }
59	      50% { r: 202; }
60	    }
61	  </style>
62	</head>
63	<body>
64	  <button class="circle-container" id="decorative-circle" aria-label="Interactive decorative circle">
65	    <svg viewBox="0 0 400 400" role="presentation">
66	      <circle cx="200" cy="200" r="200"/>
67	    </svg>
68	  </button>
69	
70	  <script>
71	    const circle = document.getElementById('decorative-circle');
72	
73	    circle.addEventListener('click', () => {
74	      circle.classList.toggle('active');
75	    });
76	  </script>
77	</body>
78	</html>
