svg {
  width: 400px;
  height: 400px;
  filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
  display: block;
}
circle {
  fill: #ffffff;
  stroke: rgba(255, 255, 255, 0.2);
  stroke-width: 2;
  transition: fill 0.3s ease, r 0.3s ease;
  animation: pulse 3s ease-in-out infinite;
}
.circle-container:hover circle,
.circle-container:focus circle {
  fill: #e8f4f8;
  r: 205;
}
@keyframes pulse {
  0%, 100% { r: 200; }
  50% { r: 202; }
}

input.new_string:
svg {
  width: min(400px, 80vw);
  height: min(400px, 80vw);
  filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
  display: block;
  transition: filter 0.3s ease;
}
circle {
  fill: #ffffff;
  stroke: rgba(255, 255, 255, 0.2);
  stroke-width: 2;
  transition: fill 0.3s ease, r 0.3s ease;
  animation: pulse 3s ease-in-out infinite;
}
.circle-container:hover circle,
.circle-container:focus circle {
  fill: #e8f4f8;
  r: 205;
}
.circle-container.active circle {
  fill: #ffd700;
  animation: pulse-active 0.6s ease-in-out;
}
.circle-container.active:hover circle {
  fill: #ffed4e;
}
.circle-container.active svg {
  filter: drop-shadow(0 20px 40px rgba(255, 215, 0, 0.5));
}
@keyframes pulse {
  0%, 100% { r: 200; }
  50% { r: 202; }
}
@keyframes pulse-active {
  0% { r: 200; }
  50% { r: 210; }
  100% { r: 200; }
}

